1	// A scenario the claim office refuses to process: the input is well-formed
2	// enough to read, but breaks a rule of the domain (an item type nobody insures,
3	// a claim against a step that never issued a policy). Distinct from a
4	// TypeError or any other bug in this module — the CLI must report a rejection
5	// as an error description and a non-zero exit, whereas a bug is a bug. Catching
6	// this type, rather than every throwable, is what keeps the two apart.
7	export class ClaimOfficeError extends Error {
8	  constructor(message: string) {
9	    super(message);
10	    this.name = "ClaimOfficeError";
11	  }
12	}
13	
14	export type QuoteResult = { premium: number };
15	
16	export type ClaimResult = { payout: number; remainingCap: number };
17	
18	export type StepResult = QuoteResult | ClaimResult;
19	
20	export type ScenarioResults = { results: StepResult[] };
21	
22	const PROCESSING_FEE = 5;
23	
24	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
25	
26	const LOYALTY_DISCOUNT_RATE = 0.2;
27	
28	const LOYALTY_THRESHOLD_YEARS = 2;
29	
30	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
31	
32	// One catalogue entry per insurable item type. Premium and insurance value are
33	// two facts about the same thing, so they live together: an item type either is
34	// in the catalogue with both, or is unknown.
35	type CatalogueEntry = { basePremium: number; insuranceValue: number };
36	
37	const ITEM_CATALOGUE: Record<string, CatalogueEntry> = {
38	  sword: { basePremium: 100, insuranceValue: 1000 },
39	  amulet: { basePremium: 60, insuranceValue: 600 },
40	  staff: { basePremium: 80, insuranceValue: 800 },
41	  potion: { basePremium: 40, insuranceValue: 400 },
42	  rune: { basePremium: 25, insuranceValue: 250 },
43	  moonstone: { basePremium: 25, insuranceValue: 250 },
44	};
45	
46	// The catalogue is the single place that decides whether an item type exists,
47	// so an unknown type fails here, by name, rather than as a stray TypeError
48	// somewhere downstream.
49	const catalogueEntryOf = (type: string): CatalogueEntry => {
50	  const entry = ITEM_CATALOGUE[type];
51	  if (entry === undefined) {
52	    throw new ClaimOfficeError(`Unknown item type: ${type}`);
53	  }
54	  return entry;
55	};
56	
57	const basePremiumOf = (type: string): number =>
58	  catalogueEntryOf(type).basePremium;
59	
60	const insuranceValueOf = (type: string): number =>
61	  catalogueEntryOf(type).insuranceValue;
62	
63	type Item = { type: string; cursed?: boolean; enchantment?: number };
64	
65	// Steps are discriminated by `op`: a quote carries the items to insure, a claim
66	// carries damage entries against a policy an earlier quote step created.
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type Incident = { cause: string; damages: Damage[] };
72	
73	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
74	
75	type Step = QuoteStep | ClaimStep;
76	
77	// Scenarios arrive as parsed JSON (from the CLI, and from object literals in
78	// the spec whose `op` widens to `string`), so the boundary type is deliberately
79	// wider than `Step`. Narrowing happens once, in `runStep`.
80	type StepInput = {
81	  op: string;
82	  items?: Item[];
83	  policy?: number;
84	  incident?: Incident;
85	};
86	
87	const isQuoteStep = (step: StepInput): step is QuoteStep =>
88	  step.op === "quote" && step.items !== undefined;
89	
90	const isClaimStep = (step: StepInput): step is ClaimStep =>
91	  step.op === "claim" && step.incident !== undefined && step.policy !== undefined;
92	
93	type Customer = { yearsWithMHPCO: number };
94	
95	type Scenario = { customer: Customer; steps: StepInput[] };
96	
97	const BLOCK_SIZE = 3;
98	
99	// A block is exactly BLOCK_SIZE components of the same type, priced as a unit.
100	// Exactly: 4 runes are not a block (4 x 25), and 2 runes + 1 moonstone is not
101	// a block either — "alike" means the same type, not the same family.
102	const BLOCK_BASE_PREMIUM = 60;
103	
104	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
105	
106	const countByType = (items: Item[]): Map<string, number> =>
107	  items.reduce(
108	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
109	    new Map<string, number>(),
110	  );
111	
112	const isBlock = (type: string, count: number): boolean =>
113	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
114	
115	const groupBasePremium = (type: string, count: number): number =>
116	  isBlock(type, count) ? BLOCK_BASE_PREMIUM : count * basePremiumOf(type);
117	
118	const sum = (numbers: number[]): number =>
119	  numbers.reduce((total, value) => total + value, 0);
120	
121	// Gold is only ever quoted in whole pieces, and every fractional amount the
122	// price list produces is resolved the same way: in the office's favor. That
123	// single rule points in opposite directions depending on which way the money
124	// moves, which is why these are two functions and not one — money coming in
125	// rounds up, money going out rounds down. Naming both sides of the rule is what
126	// keeps the asymmetry from reading as an inconsistency at the call sites.
127	const roundIncomingInOfficesFavor = (amount: number): number =>
128	  Math.ceil(amount);
129	
130	const roundOutgoingInOfficesFavor = (amount: number): number =>
131	  Math.floor(amount);
132	
133	const policyBasePremium = (items: Item[]): number =>
134	  sum(
135	    [...countByType(items)].map(([type, count]) =>
136	      groupBasePremium(type, count),
137	    ),
138	  );
139	
140	const CURSE_SURCHARGE_RATE = 0.5;
141	
142	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
143	
144	const HIGH_ENCHANTMENT_THRESHOLD = 5;
145	
146	const isCursed = (item: Item): boolean => item.cursed === true;
147	
148	const isHighlyEnchanted = (item: Item): boolean =>
149	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
150	
151	// Both surcharges can apply to the same item, so the rates add.
152	const itemSurchargeRate = (item: Item): number =>
153	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
154	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
155	
156	// Item-specific modifiers apply to the affected item's own base premium, not to
157	// the policy total — note that is the *ungrouped* base premium, so a cursed
158	// rune inside a block is surcharged on 25 G, not on a share of the block's 60.
159	const policyItemSurchargeTotal = (items: Item[]): number =>
160	  sum(
161	    items.map((item) => basePremiumOf(item.type) * itemSurchargeRate(item)),
162	  );
163	
164	const isLoyal = (customer: Customer): boolean =>
165	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
166	
167	// Policy-wide rates are summed rather than compounded, so a loyal customer's
168	// first insurance is levied at -20 % + 10 % = -10 % of the policy base premium.
169	// Every quote after the customer's first is a follow-up contract; the
170	// first-insurance surcharge still applies to it, since each item in a quote is
171	// treated as a first insurance regardless of customer history.
172	const policyModifierRate = (customer: Customer, isFollowUp: boolean): number =>
173	  (isLoyal(customer) ? -LOYALTY_DISCOUNT_RATE : 0) +
174	  (isFollowUp ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0) +
175	  FIRST_INSURANCE_SURCHARGE_RATE;
176	
177	const priceQuote = (
178	  step: QuoteStep,
179	  customer: Customer,
180	  isFollowUp: boolean,
181	): QuoteResult => {
182	  // Every modifier is a percentage of an *unmodified* base and they are all
183	  // summed, never compounded. Item surcharges are percentages of the affected
184	  // item's own base premium; policy-wide modifiers are percentages of the
185	  // policy base premium, which excludes those item surcharges. Summing the
186	  // rates before multiplying also keeps binary floating point out of trouble:
187	  // a compounded `base * (1 + rate)` chain drifts by ~1e-14, and rounding a
188	  // premium up would turn that into a whole extra gold piece.
189	  const policyBase = policyBasePremium(step.items);
190	  const premiumBeforeFee =
191	    policyBase +
192	    policyItemSurchargeTotal(step.items) +
193	    policyBase * policyModifierRate(customer, isFollowUp);
194	
195	  // The fee is added after every percentage modifier, and only the final
196	  // premium is rounded — intermediates stay fractional.
197	  return {
198	    premium: roundIncomingInOfficesFavor(premiumBeforeFee + PROCESSING_FEE),
199	  };
200	};
201	
202	// A quote is a follow-up contract when the customer already holds one, i.e.
203	// when an earlier step in this scenario was itself a quote. Preceding claim
204	// steps do not make the next quote a follow-up.
205	const isFollowUpContract = (steps: StepInput[], index: number): boolean =>
206	  steps.slice(0, index).some(isQuoteStep);
207	
208	const DEDUCTIBLE_PER_DAMAGE = 100;
209	
210	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
211	
212	// The insurance sum is the plain sum of the items' insurance values; the block
213	// discount applies to the premium only, never to the sum insured.
214	const insuranceSum = (items: Item[]): number =>
215	  sum(items.map((item) => insuranceValueOf(item.type)));
216	
217	// A policy pays out at most twice its insurance sum over its lifetime.
218	const policyCap = (items: Item[]): number =>
219	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(items);
220	
221	// Distinct from the premium-side high-enchantment *surcharge*, whose threshold
222	// is 5: this is a different rule that happens to key off the same attribute.
223	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
224	
225	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
226	
227	const FULL_REIMBURSEMENT_RATE = 1;
228	
229	const hasHighEnchantmentReimbursement = (item: Item): boolean =>
230	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD;
231	
232	// Each clause states the share of the damage it will reimburse; an item that
233	// trips no clause is reimbursed in full.
234	//
235	// The spec's second reimbursement clause — "damage to items made of dragon
236	// material is fully reimbursed" — is deliberately absent, not forgotten. It is
237	// unobservable here, on two counts:
238	//
239	//   1. It reimburses at FULL_REIMBURSEMENT_RATE, which is already the rate for
240	//      an item that trips no clause at all. On its own it changes nothing.
241	//   2. Where it competes with the high-enchantment clause, the spec says the
242	//      50 % rule wins (enchantment 9 + dragon → 400 G, same as enchantment 9
243	//      alone). So it cannot win a conflict either.
244	//
245	// No input the spec describes distinguishes an implementation with a dragon
246	// branch from this one, so `material` is not a field on `Item`. This stops
247	// holding the moment full reimbursement stops being the default — e.g. if a
248	// policy-wide co-payment is introduced — at which point the clause becomes
249	// observable and must be implemented.
250	const reimbursementRate = (item: Item): number =>
251	  hasHighEnchantmentReimbursement(item)
252	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
253	    : FULL_REIMBURSEMENT_RATE;
254	
255	// A damage is something the office pays out against; a negative one would have
256	// the customer owing the office, which the price list has no notion of.
257	const hasNegativeAmount = (damage: Damage): boolean => damage.amount < 0;
258	
259	// A reimbursement clause reduces the damage amount; the deductible comes off
260	// whatever the clause leaves.
261	const damagePayout = (damage: Damage, item: Item): number =>
262	  damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE;
263	
264	// A damage entry carries no identity beyond its type, so it is settled against
265	// any insured item of that type — and it consumes that item, so a second
266	// damage entry of the same type must find a second insured item. The pool is
267	// what is left to settle against: each match takes its item out of it.
268	type ItemPool = ReadonlyMap<string, Item[]>;
269	
270	const poolOf = (items: Item[]): ItemPool =>
271	  items.reduce(
272	    (pool, item) => pool.set(item.type, [...(pool.get(item.type) ?? []), item]),
273	    new Map<string, Item[]>(),
274	  );
275	
276	// A policy only covers what it insures, so a damage entry naming an item the
277	// policy does not carry — or one more of a type than it carries — is a
278	// rejection rather than a zero-value payout.
279	//
280	// This subsumes the unknown-item-type case, and deliberately so: the claim path
281	// never consults ITEM_CATALOGUE. Coverage is the stronger check — a policy can
282	// only hold items that passed `catalogueEntryOf` when it was quoted, so a type
283	// nobody insures is necessarily absent from the pool and is rejected here, by
284	// name. Adding a catalogue lookup on this path would be dead code: it could
285	// only fire on inputs that this lookup already rejects, and it would report the
286	// weaker of the two reasons ("unknown type" when the actionable fact is that
287	// the policy does not cover it).
288	const takeInsuredItem = (
289	  pool: ItemPool,
290	  itemType: string,
291	): { item: Item; remaining: ItemPool } => {
292	  const [item, ...rest] = pool.get(itemType) ?? [];
293	  if (item === undefined) {
294	    throw new ClaimOfficeError(
295	      `Damaged item is not covered by the policy: ${itemType}`,
296	    );
297	  }
298	  return { item, remaining: new Map(pool).set(itemType, rest) };
299	};
300	
301	// One pass over the damages, drawing down the pool as it goes: the nth damage
302	// of a type meets the nth insured item of that type, and running out is a
303	// rejection. Pairing them up front is what keeps `incidentPayout` a plain sum.
304	// A damage entry paired with the insured item it will be settled against.
305	type SettledDamage = { damage: Damage; item: Item };
306	
307	const matchDamagesToItems = (
308	  damages: Damage[],
309	  policyItems: Item[],
310	): SettledDamage[] =>
311	  damages.reduce<{ matches: SettledDamage[]; pool: ItemPool }>(
312	    ({ matches, pool }, damage) => {
313	      const { item, remaining } = takeInsuredItem(pool, damage.itemType);
314	
315	      return { matches: [...matches, { damage, item }], pool: remaining };
316	    },
317	    { matches: [], pool: poolOf(policyItems) },
318	  ).matches;
319	
320	// Well-formedness of the damages is settled before any of them is priced, so a
321	// rejection does not depend on how far a partial pass happened to get. The
322	// first offending amount names itself in the message.
323	const rejectNegativeDamages = (damages: Damage[]): void => {
324	  const negative = damages.find(hasNegativeAmount);
325	  if (negative !== undefined) {
326	    throw new ClaimOfficeError(
327	      `Damage amount cannot be negative: ${negative.amount}`,
328	    );
329	  }
330	};
331	
332	// The deductible applies once per damaged item, so each damage entry is
333	// reduced separately before the entries are summed. A damage entry names its
334	// item by type, so the clauses are read off the insured item it was matched to.
335	const incidentPayout = (incident: Incident, policyItems: Item[]): number => {
336	  rejectNegativeDamages(incident.damages);
337	
338	  return roundOutgoingInOfficesFavor(
339	    sum(
340	      matchDamagesToItems(incident.damages, policyItems).map(
341	        ({ damage, item }) => damagePayout(damage, item),
342	      ),
343	    ),
344	  );
345	};
346	
347	// The cap is a lifetime budget for the policy, so a claim can pay out only what
348	// earlier claims against the same policy have left of it.
349	const settleClaim = (
350	  step: ClaimStep,
351	  policyItems: Item[],
352	  alreadyPaidOut: number,
353	): ClaimResult => {
354	  const remainingBefore = policyCap(policyItems) - alreadyPaidOut;
355	  const payout = Math.min(
356	    incidentPayout(step.incident, policyItems),
357	    remainingBefore,
358	  );
359	
360	  return { payout, remainingCap: remainingBefore - payout };
361	};
362	
363	const quoteStepAt = (steps: StepInput[], index: number): QuoteStep => {
364	  // `policy` is a step number in the scenario, so it indexes the full step
365	  // list — not a prefix of it.
366	  const step = steps[index];
367	  if (step === undefined || !isQuoteStep(step)) {
368	    throw new ClaimOfficeError(
369	      `Claim references a step that is not a quote: ${index}`,
370	    );
371	  }
372	  return step;
373	};
374	
375	// The payouts made so far against each policy, keyed by the step index of the
376	// quote that created it. Claims consume their policy's cap as the scenario
377	// runs, so this has to be carried from each step to the next.
378	type PaidOutByPolicy = ReadonlyMap<number, number>;
379	
380	const paidOutOn = (paidOut: PaidOutByPolicy, policy: number): number =>
381	  paidOut.get(policy) ?? 0;
382	
383	const withPayoutRecorded = (
384	  paidOut: PaidOutByPolicy,
385	  policy: number,
386	  payout: number,
387	): PaidOutByPolicy =>
388	  new Map(paidOut).set(policy, paidOutOn(paidOut, policy) + payout);
389	
390	// Running a step yields its result *and* the cap ledger the next step must see.
391	// Pairing them is what lets a claim hand on the payout it just consumed without
392	// the caller having to re-derive the step's kind from its result.
393	type StepOutcome = { result: StepResult; paidOut: PaidOutByPolicy };
394	
395	// Where in the scenario a step sits. The step, the list it came from, and its
396	// index are one idea, not three arguments: both the follow-up-contract rule and
397	// the policy lookup are questions about a step's position among its siblings,
398	// and neither can be answered from the step alone. Bundling them also keeps
399	// `index` (a position) from being passed where `policy` (also a bare number,
400	// also a step index) is meant.
401	type ScenarioPosition = {
402	  step: StepInput;
403	  steps: StepInput[];
404	  index: number;
405	};
406	
407	const runStep = (
408	  { step, steps, index }: ScenarioPosition,
409	  customer: Customer,
410	  paidOut: PaidOutByPolicy,
411	): StepOutcome => {
412	  if (isQuoteStep(step)) {
413	    // A quote consumes no cap, so it passes the ledger on untouched.
414	    return {
415	      result: priceQuote(step, customer, isFollowUpContract(steps, index)),
416	      paidOut,
417	    };
418	  }
419	  if (isClaimStep(step)) {
420	    const result = settleClaim(
421	      step,
422	      quoteStepAt(steps, step.policy).items,
423	      paidOutOn(paidOut, step.policy),
424	    );
425	
426	    return {
427	      result,
428	      paidOut: withPayoutRecorded(paidOut, step.policy, result.payout),
429	    };
430	  }
431	  throw new ClaimOfficeError(`Unsupported step op: ${step.op}`);
432	};
433	
434	// What the fold carries from step to step: the results so far, plus the cap
435	// ledger. Only `results` is part of the answer — `paidOut` is scaffolding, so
436	// this is deliberately not `ScenarioResults`.
437	type ScenarioProgress = {
438	  results: StepResult[];
439	  paidOut: PaidOutByPolicy;
440	};
441	
442	export const runScenario = (scenario: Scenario): ScenarioResults => {
443	  const { results } = scenario.steps.reduce<ScenarioProgress>(
444	    ({ results, paidOut }, step, index) => {
445	      const { result, paidOut: paidOutAfter } = runStep(
446	        { step, steps: scenario.steps, index },
447	        scenario.customer,
448	        paidOut,
449	      );
450	
451	      return { results: [...results, result], paidOut: paidOutAfter };
452	    },
453	    { results: [], paidOut: new Map() },
454	  );
455	
456	  return { results };
457	};
