2	import { ClaimOfficeError, runScenario } from "./claim-office.js";
3	
4	const STDIN_FD = 0;
5	
6	// Reads stdin to EOF, so the scenario may arrive in as many chunks as the pipe
7	// cares to deliver. A scenario is a single JSON document with no terminator of
8	// its own, so there is nothing to read up to *but* EOF.
9	const readStdin = (): string => readFileSync(STDIN_FD, "utf8");
10	
11	// `JSON.parse` returns `any`, so this is the one point where unvalidated input
12	// is handed to a typed signature. `runScenario` is the validator: it narrows
13	// each step itself and rejects what it cannot read.
14	const scenario = JSON.parse(readStdin());
15	
16	const REJECTED_EXIT_CODE = 1;
17	
18	// A rejection is the office declining the scenario: report the reason and set a
19	// non-zero status, with nothing on stdout. Only ClaimOfficeError is caught —
20	// any other throw is a defect in this program, and its stack trace is the
21	// point. That includes a SyntaxError from the parse above, which is why the
22	// parse sits outside this block: the spec gives the office no answer for a
23	// malformed document, so there is no rejection to report for one.
24	try {
25	  process.stdout.write(JSON.stringify(runScenario(scenario)));
26	} catch (error) {
27	  if (!(error instanceof ClaimOfficeError)) throw error;
28	
29	  process.stderr.write(`${error.message}\n`);
30	  process.exit(REJECTED_EXIT_CODE);
31	}
